const EXPECTED_BODY = `namespace Intertech.Callcenter.Host.Operation.AgendaServices {
    using System.Diagnostics;
    using System;
    using System.Web.Services;
    using System.Data;

    public interface ZAServices {
        VisitInfo[] LastVisitInfo(string customerNo, System.Nullable<int> branch, out string message);
        System.Data.DataSet GetData();
    }

    public class VisitInfo : BaseResult {
        public string BranchName { get; set; }
        public System.DateTime VisitDate { get; set; }
        public int[] Codes { get; set; }
    }

    public class BaseResult { }

    public enum VisitKind {
        Branch,
        CallCenter,
    }
}
`;

test('a web reference proxy shrinks to its operations and data types', () => {
    const result = minimizeReference(PROXY, PROXY.length);
    assert.ok(result);
    assert.equal(result.operations, 2);
    const body = result.text.slice(result.text.indexOf('namespace'));
    assert.equal(body, EXPECTED_BODY);
    assert.ok(result.text.startsWith('//---'), 'explains itself in a header');
});

test('a file with no proxy class in it is left alone', () => {
    assert.equal(minimizeReference('namespace A { public class B { public int C { get; set; } } }', 10), null);
    // Its own output: running Shrink twice does nothing the second time.
    const once = minimizeReference(PROXY, PROXY.length)!;
    assert.equal(minimizeReference(once.text, once.text.length), null);
});

test('braces inside strings and comments do not unbalance the parser', () => {
    const tricky = PROXY.replace(
        '"http://tempuri.org/GetData"',
        '"http://tempuri.org/{GetData}" /* } */'
    ).replace('/// <remarks/>\n    public enum', '// a stray } here\n    /// <remarks/>\n    public enum');
    const result = minimizeReference(tricky, tricky.length);
    assert.ok(result);
    assert.equal(result.text.slice(result.text.indexOf('namespace')), EXPECTED_BODY);
});

test('the BOM and CRLF line endings survive', () => {
    const bytes = Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(PROXY.replace(/\n/g, '\r\n'))]);
    const out = minimizeReferenceFile(bytes)!;
    assert.deepEqual([...out.subarray(0, 3)], [0xef, 0xbb, 0xbf]);
    const text = out.subarray(3).toString('utf8');
    assert.ok(text.includes('\r\n'));
    assert.ok(!/[^\r]\n/.test(text), 'every line ends in CRLF');
    assert.ok(out.length < bytes.length / 3);
});

test('a hand-written partial class on a proxy is never taken for generated code', () => {
    const handWritten = `namespace A {
    public partial class BankServices : System.Web.Services.Protocols.SoapHttpClientProtocol {
        [System.Web.Services.Protocols.SoapDocumentMethodAttribute("x")]
        public int Custom() { return 1; }
    }
}`;
    assert.equal(looksLikeProxy(handWritten), false);
    assert.equal(minimizeReference(handWritten, handWritten.length), null);
    assert.equal(looksLikeProxy(PROXY), true);
});

test('wsdl.exe output is recognised by its header, whatever the file is called', () => {
    const wsdl = PROXY.replace('Microsoft.VSDesigner, Version 4.0.30319.42000', 'wsdl, Version=4.8.3928.0')
        .replace(/\/\/-+\n\/\/ <auto-generated>[\s\S]*?\/\/-+\n/, '//------\n// <auto-generated>\n//------\n');
    assert.equal(looksLikeProxy(wsdl), true);
    assert.ok(minimizeReference(wsdl, wsdl.length));
});
